// ============================================================
// admin.js — the owner back office, split out of app.js so public visitors
// never download it. Loaded on demand by loadAdminBundle() in app.js.
// All declarations are classic-script globals, exactly as they were in
// app.js; the footer publishes the stub targets onto window.
// ============================================================


// ---- Per-cottage GPS location for the on-arrival key-code unlock ----
function geoVal(k) {
    const g = adminPrivateContent['geo-' + k];
    return g && typeof g === 'object' && g.lat != null && g.lng != null ? g : null;
}
function geoStatusText(k) {
    const g = geoVal(k);
    return g ? 'Saved: ' + Number(g.lat).toFixed(5) + ', ' + Number(g.lng).toFixed(5) : 'Not set';
}
function setGeoInputs(k, g) {
    const latEl = document.getElementById('geo-lat-' + k);
    const lngEl = document.getElementById('geo-lng-' + k);
    if (latEl) latEl.value = g ? g.lat : '';
    if (lngEl) lngEl.value = g ? g.lng : '';
}
function captureGeo(k) {
    const status = document.getElementById('geo-status-' + k);
    if (!navigator.geolocation) {
        if (status) status.textContent = "This device can't share its location.";
        return;
    }
    if (status) status.textContent = 'Getting location…';
    navigator.geolocation.getCurrentPosition(
        async (pos) => {
            const g = { lat: pos.coords.latitude, lng: pos.coords.longitude };
            // SAVE FIRST, then adopt — clearGeo's shape, three functions down. Writing
            // the mirror before the answer repainted a refused write as a saved pin.
            try {
                await saveContent('geo-' + k, g);
            } catch (e) {
                if (status) status.textContent = "Couldn't save it just now — check your connection.";
                return;
            }
            adminPrivateContent['geo-' + k] = g;
            setGeoInputs(k, g);
            if (status) status.textContent = geoStatusText(k);
        },
        () => {
            if (status) status.textContent = "Couldn't get location (permission denied?).";
        },
        { enableHighAccuracy: true, timeout: 15000, maximumAge: 0 },
    );
}
// Save manually-typed coordinates (with basic range validation).
async function saveGeoManual(k) {
    const status = document.getElementById('geo-status-' + k);
    const lat = parseFloat((document.getElementById('geo-lat-' + k) || {}).value);
    const lng = parseFloat((document.getElementById('geo-lng-' + k) || {}).value);
    if (!isFinite(lat) || !isFinite(lng) || lat < -90 || lat > 90 || lng < -180 || lng > 180) {
        if (status)
            status.textContent = 'Enter a valid latitude (−90 to 90) and longitude (−180 to 180).';
        return;
    }
    const g = { lat, lng };
    try {
        await saveContent('geo-' + k, g);
    } catch (e) {
        if (status) status.textContent = "Couldn't save it just now — check your connection.";
        return;
    }
    adminPrivateContent['geo-' + k] = g;
    if (status) status.textContent = geoStatusText(k);
}
async function clearGeo(k) {
    const status = document.getElementById('geo-status-' + k);
    // AWAIT it, like saveGeo does. This used to fire and forget: on a failed
    // write the screen said "Not set" and the mirror agreed, while the server
    // still held the pin — the owner believed they had cleared the map location
    // and it came back on the next load.
    try {
        await saveContent('geo-' + k, '');
    } catch (e) {
        if (status) status.textContent = "Couldn't clear it just now — check your connection.";
        return;
    }
    adminPrivateContent['geo-' + k] = '';
    setGeoInputs(k, null);
    if (status) status.textContent = 'Not set';
}

// Open the Settings & Fees page (admin only)
let adminPrivateContent = {}; // includes arrival-* keys (admin-only)
let __adminPrivateLoaded = false; // has content.php get_all ever answered this session?
async function openSettings(section) {
    // The status pill lives on this page: refresh what it reads on open (both
    // are cached + best-effort, so this is cheap and never blocks).
    try {
        checkCronHealth();
    } catch (e) {}
    try {
        checkSystemHealth();
    } catch (e) {}
    if (!isAuthenticated) {
        tryAccessBackOffice();
        return;
    }
    nav('view-settings');
    adminHistPush('view-settings');
    // Show the DESTINATION now, not after two round trips. A deep link
    // (settingsOpen('payments') from search, a saved history entry) used to land
    // on the Manage index and jump into its section seconds later on a slow
    // link — the page moving under the owner, the same complaint as the openers
    // above. It opens immediately and is repainted below when the data lands.
    if (section) settingsOpen(section);
    else settingsShowIndex();
    // Load admin-only content (arrival-*, geo-*) so the per-cottage editors and
    // the host fields have their data ready when a row is opened.
    // KEEP THE LAST GOOD COPY on a failed fetch — the loadContent/loadData rule,
    // with the sharpest edge of any of them. These editors read adminPrivateContent
    // FIRST because an INTERNAL key is absent from the anonymous boot content GET,
    // so emptying it here rendered bank details, notify prefs, the tides key and
    // every cottage's arrival + welcome text BLANK over real saved data — and the
    // arrival textarea saves on CHANGE, so one typed word overwrote the lot. The
    // failure is SAID now too: a blank box the owner believes is one they fill in.
    try {
        const r = await apiPost('content.php', { action: 'get_all' });
        adminPrivateContent = r.content || {};
        __adminPrivateLoaded = true;
    } catch (e) {
        // openSettings, not openArea — openArea takes NO arguments and would
        // drop the section the owner is standing in (the trap noted in CLAUDE.md).
        if (!__adminPrivateLoaded) adminNetFail(() => openSettings(section));
    }
    // Load bookings/enquiries so the Enquiries + Guest-messages badges (and the
    // Preferences occupancy donuts) are accurate even if the back office wasn't opened.
    try {
        await loadData();
    } catch (e) {}
    try {
        refreshInboxBadge();
    } catch (e) {} // Enquiries badge (and the Home Screen app badge)
    try {
        loadAdminMessages();
    } catch (e) {} // Guest messages badge
    // Self-heal a push subscription iOS has quietly dropped. Fire-and-forget: it
    // never prompts and must not delay the back office.
    try {
        revalidateOwnerPush();
    } catch (e) {}
    // Repaint the section that opened above, now its data is in. Skipped while
    // the owner is TYPING in it: these panels are full of inputs, and a repaint
    // lands on whatever they've half-entered (the same way a blank re-render
    // would wipe the bank-details field). The window is a second or two.
    const panel = document.getElementById('settings-panel');
    const busy = !!(panel && document.activeElement && panel.contains(document.activeElement));
    if (!busy) {
        if (section) { try { settingsRenderSection(section); } catch (e) {} }
        else { try { applyAreaFilter(); } catch (e) {} }
    }
}

// ---- Back-office MANAGE: the admin sections hub (view-settings) is ONE index
// now — cottages, then marketing, then account/system, with the section labels
// as the grouping. openArea() survives as a compat alias (dock, tests, old
// history entries); the section panels (#sec-…) and settingsOpen() router are
// unchanged. ----
// ===================================================================
//  COMMAND PALETTE (⌘K) — jump to any booking, enquiry or screen from
//  anywhere in the back office. Owner-only; the markup + FAB live in
//  index.html (display:none inline, revealed by admin.css in owner-mode).
// ===================================================================
let __cmdkResults = [];
let __cmdkSel = 0;
// Sub-focus WITHIN the selected row: -1 = the row itself, 0..n index into the
// row's navigable sub-items (its quick-actions, then its refine chips), so the
// keyboard can reach "email them / take payment / refund" and the pivot pills,
// not just the row's default action. Reset whenever the row selection moves.
let __cmdkActSel = -1;
// The selected row's navigable sub-items in render order: quick-actions first,
// then the refine chips that survive the action-dedup. Returns [{kind, k}].
function cmdkRowSubItems(it, actLabels) {
    const out = [];
    if (it && Array.isArray(it.actions)) it.actions.forEach((a, k) => out.push({ kind: 'act', k }));
    if (it && Array.isArray(it.chips)) it.chips.forEach((c, k) => { if (!(actLabels && actLabels.has((c.label || '').toLowerCase()))) out.push({ kind: 'chip', k }); });
    return out;
}
let __cmdkServerT = null; // debounce timer for the deep server-side search
let __cmdkServerStamp = 0; // stale-guards late responses when the query moved on
