    // inert while it's open, and the Tab trap below keeps keyboard focus inside.
    ov.setAttribute('role', 'dialog');
    ov.setAttribute('aria-modal', 'true');
    ov.setAttribute('aria-label', 'Customer account preview' + (name ? ' — ' + name : ''));
