    const ov = document.getElementById('acct-preview-overlay');
    if (!ov) return;
    const f = [...ov.querySelectorAll('button, iframe, a[href], [tabindex]:not([tabindex="-1"])')].filter((el) => el.offsetParent !== null);
    if (!f.length) return;
    const first = f[0], last = f[f.length - 1];
