    if (was === null || was === now) return false; // first paint, or a plain refresh
    if (!tdMotionOk()) return true;
    const ord = (f) => (f === 'upcoming' ? 0 : f === 'past' ? 1 : -1);
    const a = ord(fromF), b = ord(__bookingsFilter);
