// One photo tapped: send it or stop it. The server keeps the rules — an email
// that must reach someone can't lose its last person, and says why.
async function oaMailSet(kind, id) {
    const p = (__oaPeople || []).find((x) => x.id === Number(id));
    if (!p) return;
    const on = !oaMailLit(p, kind);
    try {
        const res = await apiPost('people.php', { action: 'set_mail', id: p.id, kind, on });
        oaPeopleLanded(res);
    } catch (e) {
        const t = document.querySelector(`#emails-body [data-mail="${kind}-${p.id}"]`);
        if (t) {
            t.classList.remove('is-nudge');
            void (/** @type {HTMLElement} */ (t).offsetWidth);
            t.classList.add('is-nudge');
        }
        toast(e.message || 'That didn’t save. Try again.');
    }
}
function oaMailWhy(kind, id) {
    const p = (__oaPeople || []).find((x) => x.id === Number(id));
    if (!p) return;
    const k = (__oaMailKinds || []).find((x) => x.k === kind);
    const cap = (k && k.cap) || 'owner';
    toast(cap === 'owner' ? 'Only a Super User gets the backup. It’s everything on the site.' : p.first + ' can’t get this yet. Switch on ' + oaPermLabel(cap) + ' in What ' + p.first + ' can do first.');
}
async function oaPersonKeysLoad(id) {
    try {
        const res = await apiPost('people.php', { action: 'passkeys', id });
        OA_PERSON_KEYS[id] = res.passkeys || [];
    } catch (e) {
        OA_PERSON_KEYS[id] = [];
    }
    if (__oaPerson === id && document.querySelector('#person-body .ga-page')) {
        __oaStill = true;
        try {
            renderPerson();
        } finally {
            __oaStill = false;
        }
    }
}
async function oaPersonDo(what) {
    const p = (__oaPeople || []).find((x) => x.id === __oaPerson);
    if (!p) return;
    const n = p.first;
    if (what === 'remove' && !(await glassConfirm(n + ' is signed out everywhere straight away and can’t sign in again. Everything ' + n + ' did stays in the activity log.', 'Remove the access', { title: 'Remove ' + n + '’s access?', danger: true }))) return;
    if (what === 'cancel_invite' && !(await glassConfirm('The link in ' + n + '’s email stops working.', 'Cancel the invite', { title: 'Cancel ' + n + '’s invite?', danger: true, cancelLabel: 'Keep it' }))) return;
    let res;
    try {
        res = await apiPost('people.php', { action: what, id: p.id });
    } catch (e) {
        return glassAlert(e.message || "That didn't work. Try again.");
    }
    if (what === 'cancel_invite') {
        oaPeopleLanded(res);
        toast('Invite cancelled');
        return oaGo('people');
    }
    if (what === 'restore') delete OA_PERSON_KEYS[p.id];
    oaPeopleLanded(res);
    const sent = res && res.sent !== false;
    const say = {
        remove: n + ' no longer has access',
        restore: sent ? 'A new invite is on its way to ' + p.contact + '.' : 'Access given back, but the email didn’t send. Try “Send the invite again”.',
        reinvite: sent ? 'Invite sent again to ' + p.contact + '.' : 'The email didn’t send. Check the address and try again.',
        reset_link: sent ? 'Reset link sent to ' + p.contact + '. ' + n + ' chooses the new password.' : 'The email didn’t send. Check the address and try again.',
    }[what];
    if (say) toast(say);
}
async function oaPersonKeyRemove(keyId) {
    const p = (__oaPeople || []).find((x) => x.id === __oaPerson);
    const k = p && (OA_PERSON_KEYS[p.id] || []).find((x) => String(x.id) === String(keyId));
    if (!p || !k) return;
    const n = p.first;
    if (!(await glassConfirm(n + ' won’t be able to sign in with the passkey on ' + (k.label || 'that device') + ' any more. ' + n + '’s password still works, and ' + n + ' can add a new passkey.', 'Remove the passkey', { title: 'Remove ' + n + '’s passkey?', danger: true }))) return;
    try {
        const res = await apiPost('people.php', { action: 'passkey_remove', id: p.id, key: k.id });
        OA_PERSON_KEYS[p.id] = res.passkeys || [];
        oaPeopleLanded(res);
        toast(n + '’s passkey on ' + (k.label || 'that device') + ' removed');
    } catch (e) {
        glassAlert(e.message || "That didn't work. Try again.");
    }
}
// A screen switched off for this person (an old link, a remembered screen, a
// notification): Today instead, with the server's sentence.
function chbScreenRefused(cap) {
    if (chbCan(cap)) return false;
    toast(chbRefusal());
    nav('view-backoffice');
    return true;
}
// ---- Manage → Search learning ---------------------------------------------
// One page for the assistant's per-owner teach loop: the dead-end searches to
// teach, the phrasings you've taught it, the phrasings you've made literal, and
// the on-device model status. Built live from the same functions the in-search
// review uses — it never touches the frozen training corpus, only the owner's
// learned/suppressed/miss lists.
function slTeach(t, c) {
    try { chbNluLearn(t, c); chbMissForget(t); } catch (e) {}
    try { toast(`Taught — the assistant now answers “${t}” like “${c}”.`); } catch (e) {}
    renderSearchLearning();
}
function slForget(t) { try { chbMissForget(t); } catch (e) {} renderSearchLearning(); }
function slUnlearn(t) { try { chbNluUnlearn(t); } catch (e) {} renderSearchLearning(); }
function slRestore(t) { try { chbNluRestore(t); } catch (e) {} renderSearchLearning(); }
function slTry(t) { try { openCmdK(); const el = document.getElementById('cmdk-input'); if (el) el.value = t; cmdkSearchCore(t, true); } catch (e) {} }
// Teach a dead-end to whatever answer the owner picked from the full list (the
// picker beside a dead-end row) — closes the loop when none of the auto
// "Means: …" suggestions fit.
function slTeachSelect(t) {
    let c = '';
    try { const sel = document.getElementById('sl-canon-' + chbNluHashStr(t)); c = sel ? sel.value : ''; } catch (e) {}
    if (c) slTeach(t, c);
}
// The answerable question-types the model knows — every corpus canonical. Used
// by the "teach to any answer" picker and the "Test the assistant" verdict.
function slCanonicals() {
    try { return (CHB_NLU.corpus || []).map((c) => c.canonical).filter(Boolean); } catch (e) { return []; }
}
// ---- Guest-side learning: the questions GUESTS typed in chat that the on-device
// FAQ assistant couldn't answer (captured by guest-faq.php into the internal
// 'guest-faq-misses' content key). Manage → Guest chat lists them and turns one
// into an instant answer (gcAskedSave); Manage's "Needs a look" points there. ----
function slGuestQuestions() {
    try {
        // adminPrivateContent FIRST: an internal key is absent from the anonymous
        // boot GET, so siteContent alone read an empty list over real questions.
        const raw = gcVal('guest-faq-misses');
        const list = Array.isArray(raw) ? raw : [];
        // Most-asked first, then most-recent.
        return list.filter((r) => r && r.q).slice().sort((a, b) => (b.n || 1) - (a.n || 1) || String(b.at || '').localeCompare(String(a.at || '')));
    } catch (e) { return []; }
}
// Persist the guest-question store back (admin can write content.php). Used by
// dismiss + add-answer so a handled question leaves the list on every device.
function slGuestQuestionsSave(list) {
    try { siteContent['guest-faq-misses'] = list; if (typeof adminPrivateContent === 'object' && adminPrivateContent) adminPrivateContent['guest-faq-misses'] = list; } catch (e) {}
    try { apiPost('content.php', { action: 'set', key: 'guest-faq-misses', value: list }).catch(() => {}); } catch (e) {}
}
// "Test the assistant": read a phrasing through the SAME pipeline search uses and
// report, in plain words, whether it's understood, by which path, and what it
// would answer — so the owner can verify a lesson stuck without leaving Manage.
function slProbe(text) {
    const out = document.getElementById('sl-probe-out');
    if (!out) return;
    const q = String(text || '').trim();
    if (q.length < 2) { out.innerHTML = ''; return; }
    let built = null;
    try { built = cmdkBuildResults(q); } catch (e) {}
    const rows = (built && built.results) || [];
    const top = rows.find((r) => r && !cmdkIsNoteRow(r)) || rows[0];
    let verdict, cls;
    if (built && built.nlu) { verdict = 'Understood — matched your wording'; cls = 'ok'; }
    else if (rows.some((r) => r && r._sem)) { verdict = 'Found by meaning'; cls = 'ok'; }
    else if (top && ['answer', 'figure', 'booking', 'enquiry', 'guest', 'action', 'screen', 'field', 'help', 'review'].includes(top.type)) { verdict = 'Answered'; cls = 'ok'; }
    else if (built && built.ask && built.ask.length) { verdict = 'Not certain — it would offer the closest questions'; cls = 'warn'; }
    else { verdict = "Nothing yet — teach it below and it'll answer next time"; cls = 'muted'; }
    const ans = top ? escapeHtml(String(top.label || '').replace(/<[^>]+>/g, '')).slice(0, 90) : '';
    out.innerHTML = `<span class="sl-probe-badge sl-probe-${cls}">${verdict}</span>${ans ? `<span class="sl-probe-ans">→ ${ans}</span>` : ''}`;
}
function renderSearchLearning() {
    const wrap = document.getElementById('search-learning-body');
    if (!wrap) return;
    let misses = [], learned = [], suppressed = [];
    try { misses = chbMissList().slice().reverse(); } catch (e) {}
    try { learned = chbNluLearned().slice(); } catch (e) {}
    try { suppressed = chbNluSuppressed().slice(); } catch (e) {}
    const esc = (s) => escapeHtml(String(s == null ? '' : s));

    // 1) Plain-language model status. No jargon: what's loaded, how much it's
    // been taught, how many dead-ends are waiting.
    const statTiles = [
        ['Taught phrasings', learned.length],
        ['Made literal', suppressed.length],
        ['Dead-ends waiting', misses.length],
    ].map(([lbl, n]) => `<div class="sl-stat"><span class="sl-stat-n">${n}</span><span class="sl-stat-l">${esc(lbl)}</span></div>`).join('');
    // A "Test the assistant" sandbox — type any phrasing, see how it reads it.
    // The figures are stat tiles on the page and the sandbox is a field under them, as Guest list
    // has its tiles and its search — the sandbox was a card of its own beside nothing.
    const statusHtml = `
        <section class="glass-panel sl-card">
            <div class="sl-stats">${statTiles}</div>
            <div class="sl-probe">
                <label class="sl-probe-label" for="sl-probe-input">Test the assistant</label>
                <input id="sl-probe-input" class="input-glass" autocomplete="off" placeholder="e.g. who still hasn't coughed up" ${chbInput('slProbe')} data-pass="value">
                <div id="sl-probe-out" class="sl-probe-out"></div>
            </div>
        </section>`;

    // The answerable question-types — options for the "teach to any answer" picker.
    const canonOpts = '<option value="">Pick what it should answer…</option>' + slCanonicals().slice().sort().map((c) => `<option value="${esc(c)}">${esc(c)}</option>`).join('');

    // 2) Teach the assistant — the dead-end searches. Each row: the query, how
    // often it came up, a "Try again", up to 3 auto "Means: …" suggestions, a
    // picker to teach it to ANY answer, and Forget.
    const missRows = misses.length
        ? misses.slice(0, 30).map((m) => {
            let sugg = [];
            try { sugg = (chbNluSuggestSmart(m.t) || []).slice(0, 3); } catch (e) {}
            const suggBtns = sugg.map((c) => `<button type="button" class="btn-sm btn-edit sl-teach" ${chbAttrs('slTeach', m.t, c)}>Means: “${esc(c)}”</button>`).join('');
            const hash = chbNluHashStr(m.t);
            return `<div class="sl-row">
                <div class="sl-row-main"><span class="sl-q">“${esc(m.t)}”</span><span class="sl-meta">Searched ${m.n > 1 ? m.n + ' times' : 'once'} · found nothing</span></div>
                <div class="sl-row-acts">
                    <button type="button" class="btn-sm btn-edit" ${chbAttrs('slTry', m.t)}>Try again</button>
                    ${suggBtns}
                    <button type="button" class="btn-sm btn-edit sl-ghost" ${chbAttrs('slForget', m.t)}>Forget</button>
                </div>
                <details class="sl-more">
                    <summary>Teach it to answer something else…</summary>
                    <div class="sl-more-body">
                        <select id="sl-canon-${hash}" class="input-glass sl-canon">${canonOpts}</select>
                        <button type="button" class="btn-sm btn-edit sl-teach" ${chbAttrs('slTeachSelect', m.t)}>Teach this</button>
                    </div>
                </details>
            </div>`;
        }).join('')
        : `<p class="sl-empty">Nothing to teach — recent searches all found something. Dead-ends land here so you can teach the assistant what they meant.</p>`;

    // 3) What you've taught it — the learned phrasings, each un-teachable. A lead
    // insight names the answers you've taught the most alternatives for (where
    // the model most needed your help).
    let taughtLead = '';
    if (learned.length) {
        const byC = {};
        learned.forEach((x) => { byC[x.c] = (byC[x.c] || 0) + 1; });
        const top = Object.keys(byC).sort((a, b) => byC[b] - byC[a]).filter((c) => byC[c] >= 2).slice(0, 3);
        if (top.length) taughtLead = `<p class="sl-note" style="margin:0 0 12px;">Most-taught answers: ${top.map((c) => `“${esc(c)}” <strong>×${byC[c]}</strong>`).join(' · ')}.</p>`;
    }
    const learnRows = learned.length
        ? taughtLead + learned.slice().reverse().map((x) => `<div class="sl-row sl-row-tight">
                <div class="sl-row-main"><span class="sl-q">“${esc(x.t)}”</span><span class="sl-meta">means “${esc(x.c)}”</span></div>
                <div class="sl-row-acts"><button type="button" class="btn-sm btn-edit sl-ghost" ${chbAttrs('slUnlearn', x.t)}>Un-teach</button></div>
            </div>`).join('')
        : `<p class="sl-empty">You haven't taught it any wording yet. When a dead-end search is tagged “Means: …”, it appears here.</p>`;

    // 4) Made literal — suppressed phrasings, each restorable.
    const supRows = suppressed.length
        ? suppressed.slice().reverse().map((t) => `<div class="sl-row sl-row-tight">
                <div class="sl-row-main"><span class="sl-q">“${esc(t)}”</span><span class="sl-meta">kept literal — searched word-for-word</span></div>
                <div class="sl-row-acts"><button type="button" class="btn-sm btn-edit sl-ghost" ${chbAttrs('slRestore', t)}>Restore</button></div>
            </div>`).join('')
        : `<p class="sl-empty">None. If you ever tell search to “use the literal words”, that phrasing is remembered here so you can undo it.</p>`;

    // The four lists are VERDICT fold groups now (the fold anatomy): the
    // summary row states the conclusion, the working rows fold under it.
    // Teach-work waiting wears the amber capsule; the reference lists are
    // grey counts. The status card + probe stay above as the page's pulse.
    const teachSum = misses.length ? stCap('warn', misses.length + ' waiting') : stCap('ok', 'nothing waiting');
    const teachSub = misses.length
        ? `“${esc(misses[0].t)}”${misses.length > 1 ? ' + ' + (misses.length - 1) + ' more' : ''} found nothing`
        : '';
    const taughtSum = learned.length ? stCap('ok', learned.length + ' phrasing' + (learned.length === 1 ? '' : 's')) : stCap('unk', 'none yet');
    const supSum = suppressed.length ? stCap('unk', String(suppressed.length)) : stCap('unk', 'none');
    wrap.innerHTML =
        statusHtml +
        bhubFoldGrp('sl-teach', 'Teach the assistant', teachSub, teachSum, `<div class="sl-fold-body">${missRows}</div>`) +
        bhubFoldGrp('sl-taught', 'What you’ve taught it', '', taughtSum, `<div class="sl-fold-body">${learnRows}</div>`) +
        bhubFoldGrp('sl-literal', 'Made literal', '', supSum, `<div class="sl-fold-body">${supRows}</div>`);
}

// ---- Money → Pricing coach (data-driven suggestions; apply is opt-in) ----
async function applyPricingSuggestion(propKey, field, value, id) {
    if (field !== 'weekendPct' || !propKey) return;
    const prevPct = parseFloat((propertyRates[propKey] || {}).weekendPct) || 0;
    try {
        await updateRate(propKey, 'weekendPct', value); // existing validated save path
        chbUndoRecord(`${Number(value)}% weekend uplift on ${(propertyMeta[propKey] || {}).name || propKey}`, async () => {
            await updateRate(propKey, 'weekendPct', prevPct);
            try { toast(`Undone — weekend uplift back to ${prevPct}%.`); } catch (e) {}
        });
        const el = document.getElementById('psug-' + id);
        if (el)
            el.innerHTML = `<p style="font-size:var(--fs-body);color:var(--ok-text);margin:0;">✓ Applied — weekend uplift set to ${Number(value)}% for ${escapeHtml((propertyMeta[propKey] || {}).name || propKey)}. Adjust any time in Cottages → ${escapeHtml((propertyMeta[propKey] || {}).name || propKey)} → Rates.</p>`;
        try {
            toast('Weekend pricing updated.');
        } catch (e) {}
        try { renderPricing(); } catch (e) {}
    } catch (e) {
        glassAlert("Couldn't apply: " + e.message);
    }
}

// ---- Manage → Website content (form-based editor for the global homepage /
// nav text + images that used to be edited inline via edit-mode). Reads each
// field's CURRENT value straight off the live element, saves via saveContent,
// and updates the page immediately. Per-cottage text/photos live under
// Preferences → [cottage]; this excludes the cottage-template fields. ----
const CONTENT_LABELS = {
    'site-logo': 'Site name',
    'hero-kicker': 'Hero kicker (small line above the heading)',
    'hero-title': 'Hero heading',
    'hero-sub': 'Hero subheading',
    'hero-btn': 'Hero button',
    'hero-bg': 'Hero background image',
    'card1-title': 'Cottage 1 — card title',
    'card1-meta': 'Cottage 1 — card subtitle',
    'card1-img': 'Cottage 1 — card photo',
    'card2-title': 'Cottage 2 — card title',
    'card2-meta': 'Cottage 2 — card subtitle',
    'card2-img': 'Cottage 2 — card photo',
    'card3-title': 'Cottage 3 — card title',
    'card3-meta': 'Cottage 3 — card subtitle',
    'card3-img': 'Cottage 3 — card photo',
    'nav-home': 'Menu: Home',
    'nav-cottages': 'Menu: Cottages',
    'nav-experiences': 'Menu: Things to do',
    'nav-book': 'Menu: Book',
    'mnav-home': 'Mobile menu: Home',
    'mnav-cottages': 'Mobile menu: Cottages',
    'mnav-experiences': 'Mobile menu: Things to do',
    'mnav-book': 'Mobile menu: Book',
    'amenities-title': 'Amenities heading',
    'terms-title': 'Terms heading',
    'cal-add-btn': 'Calendar “add” button',
};
function contentBgUrl(el) {
    const m = (el.style.backgroundImage || '').match(/url\(["']?([^"')]+)["']?\)/);
    return m ? m[1] : '';
}
function loadContentEditor() {
    const wrap = document.getElementById('content-editor');
    if (!wrap) return;
    // Per-cottage fields live under Preferences → [cottage]: the cottage detail
    // template (#view-21a) AND the home-page cards (card1/2/3 → each cottage's
    // own "Website content" folder). This page keeps only the site-wide bits.
    const skip = (el) =>
        !!el.closest('#view-21a') ||
        /^card[123]-(img|title|meta)$/.test(
            el.getAttribute('data-edit-text') || el.getAttribute('data-edit-img') || '',
        );
    const imgs = [...document.querySelectorAll('[data-edit-img]')].filter((el) => !skip(el));
    const texts = [...document.querySelectorAll('[data-edit-text]')].filter((el) => !skip(el));
    const seen = new Set();
    const label = (k) => CONTENT_LABELS[k] || k;
    // Two verdict fold groups (the fold anatomy) with the REAL editors inside —
    // every field keeps its ce-<key> id, so contentEditSave/contentEditImage
    // and the poorsignal gate's direct calls work unchanged inside the fold.
    let imgRows = '';
    imgs.forEach((el) => {
        const k = el.getAttribute('data-edit-img');
        if (seen.has(k)) return;
        seen.add(k);
        imgRows +=
            `<div class="content-edit-row"><div class="exp-edit-thumb" id="ce-thumb-${k}" style="background-image:url('${escapeHtml(contentBgUrl(el))}');"></div>` +
            `<div style="flex:1;min-width:0;"><div class="modal-label" style="margin:0 0 6px;">${escapeHtml(label(k))}</div>` +
            `<button class="btn-sm btn-edit" ${chbAttrs('contentEditImage', String(k))}>Replace image</button></div></div>`;
    });
    const nImgs = seen.size;
    let textRows = '';
    let nTexts = 0;
    texts.forEach((el) => {
        const k = el.getAttribute('data-edit-text');
        if (seen.has(k)) return;
        seen.add(k);
        nTexts++;
        const val = (el.textContent || '').trim();
        const field =
            val.length > 60
                ? `<textarea class="input-glass" id="ce-${k}" rows="2" style="resize:vertical;">${escapeHtml(val)}</textarea>`
                : `<input type="text" class="input-glass" id="ce-${k}" value="${escapeHtml(val)}">`;
        textRows +=
            `<div style="margin-bottom:14px;max-width:640px;"><label class="modal-label" for="ce-${k}">${escapeHtml(label(k))}</label>${field}` +
            `<button class="btn-sm btn-edit" style="margin-top:6px;" ${chbAttrs('contentEditSave', String(k))}>Save</button></div>`;
    });
    wrap.innerHTML =
        bhubFoldGrp('wc-images', 'Images', '', stCap(nImgs ? 'ok' : 'unk', nImgs ? nImgs + ' image' + (nImgs === 1 ? '' : 's') : 'none found'), `<div class="sl-fold-body">${imgRows}</div>`) +
        bhubFoldGrp('wc-text', 'Text &amp; wording', '', stCap(nTexts ? 'ok' : 'unk', nTexts ? nTexts + ' field' + (nTexts === 1 ? '' : 's') : 'none found'), `<div class="sl-fold-body">${textRows}</div>`);
}
// The green border is a CLAIM, so it waits for the save. It used to flash on a
// rejected write (saveContent rethrows; the catch swallowed it) — the same defect
// as saveHostText's "Saved.", on a field the owner then navigates away from
// believing their text is on the site.
async function contentEditSave(key) {
    const el = document.getElementById('ce-' + key);
    if (!el) return;
    const val = el.value;
    siteContent[key] = val;
    document.querySelectorAll('[data-edit-text="' + key + '"]').forEach((t) => {
        t.textContent = val;
    });
    try {
        await saveContent(key, val);
    } catch (e) {
        el.style.borderColor = 'var(--danger)';
        setTimeout(() => { el.style.borderColor = ''; }, 2400);
        return;
    }
    el.style.borderColor = 'var(--ok)';
    setTimeout(() => {
        el.style.borderColor = '';
    }, 1200);
}
function contentEditImage(key) {
    pickAndUpload('content-' + key, async (url) => {
        await saveContent(key, url);
        siteContent[key] = url;
        document.querySelectorAll('[data-edit-img="' + key + '"]').forEach((t) => {
            t.style.backgroundImage = `url('${url}')`;
        });
        const th = document.getElementById('ce-thumb-' + key);
        if (th) th.style.backgroundImage = `url('${url}')`;
    });
}
// ---- Manage → Text messages (Twilio) ---------------------------------------
// The four settings used to be config.php constants, so switching SMS on meant
// editing a PHP file on the host — and because the enquiry form offered "Text me
// booking updates" regardless, a guest could tick a box that nothing could act
// on. They are owner-editable now.
//
// The AUTH TOKEN is write-only: content.php's get_all refuses to decrypt it into
// any browser payload, so this page never has the value to show. The field is
// therefore always blank and blank means KEEP — which is why saving reads the
// status back afterwards rather than assuming what it wrote.
let __smsStatus = null;
// The fields are all <input>s; getElementById types them as bare HTMLElement, so
// one cast here beats nine at the call sites (the tsc ratchet is on a budget).
const smsEl = (id) => /** @type {HTMLInputElement|null} */ (document.getElementById(id));
async function renderSms() {
    const on = smsEl('sms-on');
    const sid = smsEl('sms-sid');
    const from = smsEl('sms-from');
    const tok = smsEl('sms-token');
    if (tok) tok.value = ''; // never prefilled — see above
    const msg = document.getElementById('sms-msg');
    if (msg) msg.textContent = '';
    const tmsg = document.getElementById('sms-test-msg');
    if (tmsg) tmsg.textContent = '';
    smsPaintState(null); // "Checking…" until the server answers
    let st = null;
    try {
        const r = await apiPost('diagnostics.php', { action: 'sms_status' });
        st = (r && r.sms) || null;
    } catch (e) {
        smsPaintState('error');
        return;
    }
    __smsStatus = st;
    if (!st) return;
    if (on) on.checked = !!st.on;
    // The SID is an identifier, not a credential, so it round-trips — but the
    // server only ever sends its last 4, enough to confirm WHICH account.
    if (sid) sid.value = st.sid_set ? '' : '';
    if (sid) sid.placeholder = st.sid_set ? '•••• ' + (st.sid_tail || '') + ' — blank keeps it' : 'AC…';
    if (from) from.value = st.from || '';
    // Whether a token is saved rides the field itself, as the SID's does.
    if (tok) tok.placeholder = st.token_set ? 'Saved — blank keeps it' : 'Paste the auth token';
    smsPaintState(st);
    // A config.php constant silently outranks everything on this page, so say so
    // rather than letting the owner edit fields that cannot take effect.
    [on, sid, from, tok].forEach((el) => {
        if (el) el.disabled = !!(st && st.from_config);
    });

}
// The page's state is the Manage pill beside its title (the one look's status rule); its words
// carry the full sentence as the pill's name. The one fact a pill cannot carry stays as a quiet
// line: settings set on the server make this page read-only.
function smsPaintState(st) {
    const el = document.getElementById('sms-state');
    const pill = (tone, text, label) => {
        if (settingsShowing('sms')) headPillSet('settings-panel-cap', headPill(tone, text, { label }));
    };
    if (el) {
        el.textContent = '';
        el.hidden = true;
    }
    if (st === null) return pill('unk', 'Checking…', 'Checking whether texts are set up');
    if (st === 'error') return pill('unk', 'Couldn’t check', "Couldn't check whether texts are set up.");
    if (st.from_config) {
        if (el) {
            el.textContent = 'Set on the server, so this page is read-only.';
            el.hidden = false;
        }
        return pill('ok', 'Set on the server', 'Texts are already set up on the server, and those settings win — so this page is read-only.');
    }
    if (st.ready) return pill('ok', 'Texts on', 'Texts are on.');
    if (st.on) return pill('warn', 'Not ready', 'Switched on, but not usable yet — fill in all three Twilio details below.');
    return pill('unk', 'Texts off', 'Texts are off.');
}
async function saveSmsSettings() {
    const msg = document.getElementById('sms-msg');
    const say = (t, ok) => { if (msg) { msg.style.color = ok ? 'var(--ok-text)' : 'var(--danger-text)'; msg.textContent = t; } };
    const val = (id) => ((smsEl(id) || { value: '' }).value || '').trim();
    const on = !!(smsEl('sms-on') || { checked: false }).checked;
    const sid = val('sms-sid');
    const token = val('sms-token');
    const from = val('sms-from');
    // Refuse to switch ON without the details, rather than saving a state whose
    // own status line would immediately call it unusable.
    const known = __smsStatus || {};
    if (on && !sid && !known.sid_set) { say('Add the Account SID before switching texts on.', false); return; }
    if (on && !token && !known.token_set) { say('Add the Auth token before switching texts on.', false); return; }
    if (on && !from) { say('Add your Twilio number before switching texts on.', false); return; }
    if (from && !/^\+\d{8,15}$/.test(from)) { say('The Twilio number needs its country code, e.g. +447700900000.', false); return; }
    try {
        // A BLANK secret means "leave it alone", so it is simply not sent — the
        // opposite of the usual save-what-is-on-screen, and the only way a
        // write-only field can work.
        await apiPost('content.php', { action: 'set', key: 'sms-from', value: from });
        if (sid) await apiPost('content.php', { action: 'set', key: 'apikey-twilio-sid', value: sid });
        if (token) await apiPost('content.php', { action: 'set', key: 'apikey-twilio-token', value: token });
        await apiPost('content.php', { action: 'set', key: 'sms-enabled', value: on ? '1' : '' });
        say('Saved ✓', true);
        await renderSms(); // re-read: the server decides what is actually usable
    } catch (e) {
        say("Couldn't save: " + e.message, false);
    }
}
async function sendSmsTest() {
    const msg = document.getElementById('sms-test-msg');
    const say = (t, ok) => { if (msg) { msg.style.color = ok ? 'var(--ok-text)' : 'var(--danger-text)'; msg.textContent = t; } };
    const to = ((smsEl('sms-test-to') || { value: '' }).value || '').trim();
    if (!to) { say('Type your mobile number first.', false); return; }
    say('Sending…', true);
    try {
        const r = await apiPost('diagnostics.php', { action: 'sms_test', to });
        if (r && r.ok) say('Sent to ' + (r.to || to) + ' — check your phone.', true);
        else say(r && r.error ? r.error : "Couldn't send.", false);
    } catch (e) {
        say("Couldn't send: " + e.message, false);
    }
}

// ---- Manage → API keys ----
function renderApis() {
    const el = document.getElementById('apikey-tides-input');
    if (el) el.value = (adminPrivateContent && adminPrivateContent['apikey-tides']) || '';
    const msg = document.getElementById('apikey-tides-msg');
    if (msg) msg.textContent = '';
}
async function saveApiKey(which) {
    if (which !== 'tides') return;
    const el = document.getElementById('apikey-tides-input');
    const msg = document.getElementById('apikey-tides-msg');
    const val = ((el && el.value) || '').trim();
    try {
        await apiPost('content.php', { action: 'set', key: 'apikey-tides', value: val });
        if (adminPrivateContent) adminPrivateContent['apikey-tides'] = val;
        __tideData = null; // re-fetch with the new key next time
        if (msg) {
            msg.style.color = 'var(--ok-text)';
            msg.textContent = val ? 'Saved ✓' : 'Cleared — tide widget hidden.';
        }
    } catch (e) {
        if (msg) {
            msg.style.color = 'var(--danger-text)';
            msg.textContent = "Couldn't save: " + e.message;
        }
    }
}
// "Create then fill in": just a name + nightly couple rate. The server
// generates the key/slug/accent; everything else is completed afterwards in
// the new cottage's Preferences folders. All booking/payment logic works for
// it immediately because it's a real properties row.
// ONE FORM, AND BACKING OUT CREATES NOTHING. This was three dialogs ending in a
// glassConfirm used as a two-way choice — "OK = private · Cancel = list it publicly"
// — with no third branch, and glassConfirm resolves FALSE on Cancel AND Escape. So
// an owner who changed their mind at the last step, or reflexively dismissed the
// dialog, PUBLISHED a cottage to the live website: no photos, no description,
// enquirable at once. glassForm resolves null on both.
async function addAccommodationPrompt() {
    const vals = await glassForm(
        'A new cottage needs a name and a nightly price for a couple. You can change everything else afterwards.',
        [
            { id: 'name', label: 'Name', type: 'text', placeholder: 'e.g. Harbour Cottage' },
            { id: 'rate', label: 'Nightly price for a couple (£)', type: 'number', placeholder: '130' },
            {
                id: 'listing',
                label: 'On the website?',
                type: 'select',
                options: [
                    { value: 'public', label: 'Show it on the website' },
                    { value: 'private', label: "Private — don't show it, but take bookings for it" },
                ],
            },
        ],
        { title: 'Add an accommodation', okLabel: 'Add it' },
    );
    if (!vals) return; // Cancel or Escape — nothing is created
    const name = String(vals.name || '').trim();
    if (!name) {
        glassAlert('Please enter a name.');
        return;
    }
    const rate = parseFloat(vals.rate);
    if (!(rate > 0)) {
        glassAlert('Please enter a nightly couple rate above £0.');
        return;
    }
    const unlisted = vals.listing === 'private';
    try {
        const res = await apiPost('rates.php', {
            action: 'create',
            name: name,
            couple_rate: rate,
            unlisted: unlisted ? 1 : 0,
        });
        await loadRates();
        try { renderCottagesOverview(); } catch (e) {}
        if (res && res.prop_key) settingsOpenAccom(res.prop_key); // drop straight into "fill in"
        toast(
            unlisted
                ? `Added private cottage "${name}" — book it from the calendar or Add booking.`
                : `Added "${name}" — now add its photos & details.`,
        );
    } catch (e) {
        glassAlert("Couldn't add the accommodation: " + (e && e.message ? e.message : e));
    }
}
// Toggle a cottage's private (unlisted) state from its Preferences detail.
async function setAccommodationPrivate(k, makePrivate) {
    const name = (propertyMeta[k] && propertyMeta[k].name) || k;
    if (makePrivate) {
        const ok = await glassConfirm(
            `Make "${name}" private?\n\nIt will be removed from your public website, but its bookings, payments and history are kept and you can still take new bookings for it in the back office.`,
            'Make it private',
        );
        if (!ok) return;
    }
    try {
        await apiPost('rates.php', { action: 'set_unlisted', prop_key: k, unlisted: makePrivate ? 1 : 0 });
        await loadRates();
        accomAfterChange(k);
        toast(makePrivate ? `"${name}" is now private (off the website).` : `"${name}" is now public on your website.`);
    } catch (e) {
        glassAlert("Couldn't update it: " + (e && e.message ? e.message : e));
    }
}
async function archiveAccommodation(k) {
    const name = (propertyMeta[k] && propertyMeta[k].name) || k;
    // Archiving is fully reversible (restore), so skip the confirm dialog and
    // offer an immediate Undo instead — one tap, with a safety net right there.
    try {
        await apiPost('rates.php', { action: 'archive', prop_key: k });
        await loadRates();
        accomAfterChange(k, true);
        toast(`"${name}" removed from the site — bookings & history kept.`, undefined, {
            label: 'Undo',
            fn: () => restoreAccommodation(k),
        });
    } catch (e) {
        glassAlert("Couldn't remove it: " + (e && e.message ? e.message : e));
    }
}
async function restoreAccommodation(k) {
    const name = (propertyMeta[k] && propertyMeta[k].name) || k;
    try {
        await apiPost('rates.php', { action: 'unarchive', prop_key: k });
        await loadRates();
        accomAfterChange(k);
        toast(`"${name}" restored — live on the site again.`);
    } catch (e) {
        glassAlert("Couldn't restore it: " + (e && e.message ? e.message : e));
    }
}
