    f.past.forEach((s) => facts.push(['Stayed', fmtStayRange(String(s.b.checkIn || '').slice(0, 10), String(s.b.checkOut || '').slice(0, 10)) + ' · ' + escapeHtml((propertyMeta[s.pk] || {}).name || s.pk), gstAmt(s)]));
