    S.mine.forEach((c) => { h += row(pmDot(c.k) + escapeHtml(c.name), 'After card fees', gbp(c.net), { fig: 'n-' + c.k }); });
    if (Math.abs(S.other || 0) > 0.005) h += row('Not tied to a cottage', 'After card fees', gbp(S.other));
