// Email the guest a secure pay link (deposit or balance).
async function requestPayment(bookingId, kind, via) {
    const booking = findBookingById(bookingId);
    if (!booking) return false;
    return await previewAndSendEmail({
        id: booking.dbId,
        kind: 'payment.request',
        to: booking.email,
        sendLabel: `Send ${kind === 'balance' ? 'balance' : 'deposit'} request`,
        fallbackConfirm: `Email ${booking.name || 'the guest'} a ${kind === 'balance' ? 'balance' : 'deposit'} payment request?`,
        doSend: async () => {
            try {
                const body = { action: 'request_payment', id: booking.dbId, kind };
                if (via) body.via = via; // the AI card's send is attributed in the log
                const res = await apiPost('bookings.php', body);
                toast(`${kind === 'balance' ? 'Balance' : 'Deposit'} request sent — ${gbp(res.amount)}.`);
            } catch (e) {
                // "It already went" is INFORMATION, not a failure — the guest has the
                // email, which is what the owner wanted. It did not go NOW either way.
                if (e && e.code === 'already_sent') toast(e.message);
                else glassAlert("Couldn't send the payment request: " + e.message);
                return false;
            }
        },
    });
}
// ---- Per-booking payment plan (the hub's plan panel) -----------------------
// DISPLAY mirrors of pricing.php's booking_deposit_amount / booking_balance_due_date
// — the panel describes the plan; every figure a guest is ever ASKED for is still
// derived server-side from the same stored fields, so the two can only disagree
// if one of these drifts from its PHP twin (kept adjacent-by-name on purpose).
// `total` is the RENTAL total (paymentSummary().total), the frame the schedule
// is defined in — the damages deposit rides the first charge separately.
function bookingPlanDeposit(b, total) {
    if (b.depositAmountOverride > 0) return Math.round(Math.min(b.depositAmountOverride, total) * 100) / 100;
    if (b.depositPctOverride > 0 && b.depositPctOverride <= 100) return Math.round(total * b.depositPctOverride) / 100;
    return Math.round(total * (paymentTerms.depositPct || 25)) / 100;
}
function bookingPlanDueDate(b) {
    if (b.balanceDueDate) return b.balanceDueDate;
    if (!b.checkIn) return '';
    const std = ukShiftDays(b.checkIn, -(paymentTerms.balanceDays || 30));
    // A booking made INSIDE the balance window owes in full on the day it was
    // made — never weeks before it existed (that read as long overdue on Money
    // while Today said "arriving in 5 days").
    const made = String(b.agreedOn || b.createdAt || '').slice(0, 10);
    return /^\d{4}-\d{2}-\d{2}$/.test(made) && made > std ? made : std;
}
// The plan, stated as sentences inside the Payments header. Hidden once a
// standard-plan booking is settled (nothing left to schedule); a CUSTOM plan
// stays visible as the record of what was agreed. Dates lead each line's
// provenance so "why this figure?" is answered where the figure is.
// DISPLAY mirrors of pricing.php's schedule maths (ukShiftMonthsPhp /
// booking_instalment_schedule) — panel rendering only; every charged figure
// stays server-derived. Month steps clamp the day into short months.
function apShiftMonths(iso, months) {
    const p = String(iso || '').slice(0, 10).split('-').map(Number);
    if (p.length !== 3 || !p[0]) return String(iso);
    let y = p[0], m0 = p[1] - 1 + months;
    y += Math.floor(m0 / 12);
    const m = ((m0 % 12) + 12) % 12;
    const last = new Date(Date.UTC(y, m + 1, 0)).getUTCDate();
    return `${y}-${String(m + 1).padStart(2, '0')}-${String(Math.min(p[2], last)).padStart(2, '0')}`;
}
function apSchedule(due, n) {
    const out = [];
    for (let i = n - 1; i >= 0; i--) out.push(apShiftMonths(due, -i));
    return out;
}
// ---- The floor under the monthly offer (Manage → Payments) -----------------
// DISPLAY mirror of pricing.php's instalment_floor_months — the offer itself
// is always derived server-side. adminPrivateContent FIRST (the bacs-details
// rule): an internal key is absent from the anonymous boot GET.
function apFloorMonths() {
    const apc = typeof adminPrivateContent === 'object' && adminPrivateContent ? adminPrivateContent : {};
    const raw = apc['instalment-floor-months'] !== undefined ? apc['instalment-floor-months'] : siteContent['instalment-floor-months'];
    const v = parseInt(String(raw == null ? '' : raw), 10);
    return v >= 1 && v <= 6 ? v : 0;
}
// The runway LADDER: what the offer yields per band of time-before-due, the
// floor drawn as a line across it. DISPLAY ONLY — the bands restate
// booking_instalment_offer's arithmetic (a month of room per instalment, a
// week's clearance on the first). `line` = the row the floor sits above, −1
// when off. Pure, so search-test drives every floor value.
function apFloorLadderRows(floor) {
    const bands = [
        { min: 3, lead: 'More than 3 months', offer: 'Up to 4 payments' },
        { min: 2, lead: '2 – 3 months', offer: '3 payments' },
        { min: 1, lead: '1 – 2 months', offer: '2 payments' },
    ];
    const rows = [];
    if (!(floor >= 1)) {
        for (const b of bands) rows.push({ lead: b.lead, offer: b.offer, dim: false });
        rows.push({ lead: 'Under ~5 weeks', offer: 'No plan fits — one payment only', dim: true });
        return { rows, line: -1 };
    }
    for (const b of bands) {
        if (b.min >= floor) rows.push({ lead: b.lead, offer: b.offer, dim: false });
    }
    // A floor above every band (4 months) still states what survives it.
    if (!rows.length) rows.push({ lead: `More than ${floor} months`, offer: 'Up to 4 payments', dim: false });
    const line = rows.length;
    rows.push({ lead: `Under ${floor} months`, offer: 'No monthly offered', dim: true });
    rows.push({ lead: 'Under ~5 weeks', offer: 'No plan would fit anyway', dim: true });
    return { rows, line };
}
function apFloorLadderHtml(floor) {
    const { rows, line } = apFloorLadderRows(floor);
    let html = '';
    rows.forEach((r, i) => {
        if (i === line) html += `<div class="apfl-line"><span>Your cut-off · ${floor} months</span></div>`;
        html += `<div class="apfl-rung${r.dim ? ' is-dim' : ''}"><span class="apfl-lead">${r.lead}</span><span class="apfl-dots"></span><span class="apfl-offer">${r.offer}</span></div>`;
    });
    return html;
}
// The cut-off is a four-way switch (Any time / 2 / 3 / 4 months) that SAVES AS IT
