// Copy a secure pay link to the clipboard, to share by WhatsApp/SMS/etc.
// ONE pay link — it names no stage, so this takes none. The hardcoded 'balance'
// it used to pass became `&k=` in the URL: a claim made at COPY time, stale by
// the time the guest used it.
async function copyPayLink(bookingId) {
    const booking = findBookingById(bookingId);
    if (!booking) return;
    try {
        const res = await apiPost('bookings.php', { action: 'pay_link', id: booking.dbId });
        const url = res.url || '';
        if (!url) throw new Error('No link returned.');
        let copied = false;
        try {
            await navigator.clipboard.writeText(url);
            copied = true;
        } catch (e) {
            /* clipboard blocked */
        }
        if (copied) toast('Pay link copied to clipboard.');
        else await glassAlert('Copy this secure pay link:\n\n' + url);
    } catch (e) {
        glassAlert("Couldn't get the pay link: " + e.message);
    }
}
// ---- Refundable damage deposit (charged upfront, refunded on approval) ----
function holdControls(b) {
    if (typeof squareAdminEnabled === 'undefined' || !squareAdminEnabled || !b.email) return '';
    const amt = b.holdAmount || (b.agreedPrice ? b.agreedPrice.damagesDeposit : 0) || 0;
    if (amt <= 0) return '';
    const st = b.holdStatus || 'none';
    // UK clock, not UTC — during BST the UTC date lags the UK date 00:00–01:00,
    // which would show the deposit refund controls an hour late and disagree with
    // the time-aware needs-you strip (hasCheckedOut).
    const left = b.checkOut && (typeof hasCheckedOut === 'function' ? hasCheckedOut(b) : b.checkOut <= todayDashed());
    // New charge-upfront model.
    if (st === 'charged') {
        const actions = left
            ? `<button class="btn-sm btn-edit" ${chbAttrs('returnDeposit', String(b.id))}>Approve &amp; refund</button>
               <button class="btn-sm btn-edit" ${chbAttrs('keepDeposit', String(b.id))}>Keep (damage)</button>`
            : `<span style="color:var(--text-muted);font-size:var(--fs-caption);">refundable after checkout</span>`;
        return `<div class="money-deposit"><span>Damage deposit: <strong>${gbp(amt)} collected</strong></span> ${actions}</div>`;
    }
    if (st === 'returned')
        return `<div class="money-deposit"><span>Damage deposit: <span style="color:var(--ok-text);">${gbp(amt)} refunded</span></span></div>`;
    if (st === 'kept')
        return `<div class="money-deposit"><span>Damage deposit: <strong style="color:var(--danger-text);">${gbp(amt)} kept</strong> for damage</span></div>`;
    // Legacy card-hold model — kept working for any in-flight authorised holds.
    if (st === 'authorized')
        return `<div class="money-deposit"><span>Damage hold: <strong>${gbp(amt)} held</strong></span>
                <button class="btn-sm btn-edit" ${chbAttrs('releaseHold', String(b.id))}>Release</button>
                <button class="btn-sm btn-edit" ${chbAttrs('captureHold', String(b.id))}>Capture (damage)</button></div>`;
    if (st === 'captured')
        return `<div class="money-deposit"><span>Damage hold: <strong style="color:var(--danger-text);">${gbp(amt)} captured</strong> for damage</span></div>`;
    if (st === 'released')
        return `<div class="money-deposit"><span>Damage hold: <span style="color:var(--ok-text);">released</span></span></div>`;
    if (st === 'expired')
        return `<div class="money-deposit"><span>Damage hold: expired (auto-released)</span></div>`;
    // Fresh booking: nothing to render — the unified payline's "incl. £X damages
    // deposit" suffix already tells this story, and a second note read as clutter.
    return '';
}
async function keepDeposit(bookingId) {
    const booking = findBookingById(bookingId);
    if (!booking) return;
    if (
        !(await glassConfirm(
            'Keep the damage deposit (there was damage)? The guest will NOT be refunded. This is recorded as retained income.',
            'Keep it',
        ))
    )
        return;
    try {
        const res = await apiPost('bookings.php', { action: 'keep_deposit', id: booking.dbId });
        toast(`Deposit kept — ${gbp(res.kept)}.`);
        // Keeping a deposit is the strongest rating moment of all — the fold
        // opens on the re-render (an offer, never a nag; see returnDeposit).
        __gbDraft = null;
        __bhubOpenFolds.add('rating');
        // Re-read the booking + the returns BEFORE repainting: the hub otherwise
        // went on saying "£75 still held" with Return offered beside it.
        try {
            await loadData();
            if (typeof loadDepositReturns === 'function') await loadDepositReturns();
        } catch (e2) {}
        afterPaymentChange(bookingId);
    } catch (e) {
        glassAlert("Couldn't keep the deposit: " + e.message);
    }
}
async function captureHold(bookingId) {
    const booking = findBookingById(bookingId);
    if (!booking) return;
    if (
        !(await glassConfirm(
            'Capture the full damage hold? Use this only if there IS damage — it takes the held amount. (If the damage was less, capture then refund the difference.)',
            'Capture the hold',
        ))
    )
        return;
    try {
        const res = await apiPost('bookings.php', { action: 'hold_capture', id: booking.dbId });
        toast(`Hold captured — ${gbp(res.captured)}.`);
        try {
            await loadData();
            renderMoneyPanel();
        } catch (e) {}
    } catch (e) {
        glassAlert("Couldn't capture the hold: " + e.message);
    }
}
async function releaseHold(bookingId) {
    const booking = findBookingById(bookingId);
    if (!booking) return;
    if (
        !(await glassConfirm(
            "Release the damage hold? This frees the held funds on the guest's card.",
            'Release the hold',
        ))
    )
        return;
    try {
        await apiPost('bookings.php', { action: 'hold_release', id: booking.dbId });
        toast('Hold released.');
        try {
            await loadData();
            renderMoneyPanel();
        } catch (e) {}
    } catch (e) {
        glassAlert("Couldn't release the hold: " + e.message);
    }
}

