                <div class="pr-limits${s.smart ? '' : ' is-off'}">
                    ${step('floor', 'Never suggest below', '', s.floor ? `£${s.floor}` : 'No limit', 'Lowest suggestion')}
                    ${step('ceil', 'Never suggest above', '', s.ceil ? `£${s.ceil}` : 'No limit', 'Highest suggestion')}
                </div>
