async function tcSeedFeatures(btn) {
    const msg = document.getElementById('tc-seed-msg');
    if (btn) {
        btn.disabled = true;
        btn.textContent = 'Seeding…';
    }
    try {
        const r = await apiPost('testcentre.php', { action: 'seed_features' });
        if (msg) {
            if (r.ok) {
                msg.style.color = 'var(--ok-text)';
                msg.innerHTML = `✓ Demo data seeded across ${r.cottages} cottage${r.cottages === 1 ? '' : 's'}. Work through the checklist below — open <strong>Preview as guest</strong> for the public-facing items and <strong>Manage → Pricing</strong> for the suggestions.`;
            } else {
                msg.style.color = 'var(--danger-text)';
                msg.textContent = r.error || 'Seeding failed.';
            }
        }
        // Refresh admin-side data so the calendar/cards reflect it without a reload.
        try {
            await loadData();
        } catch (e) {}
        try {
            await loadRates();
        } catch (e) {}
    } catch (e) {
        if (msg) {
            msg.style.color = 'var(--danger-text)';
            msg.textContent = 'Could not seed: ' + (e.message || 'error');
        }
    } finally {
        if (btn) {
            btn.disabled = false;
            btn.textContent = 'Seed demo data';
        }
    }
}
