                    <span class="al-txt"><span class="al-title">${alHi(title, q)}${it.more.length ? ` <span class="al-x">×${it.more.length + 1}</span>` : ''}</span>${meta ? `<span class="al-meta">${escapeHtml(meta)}</span>` : ''}</span>
